// v8 Phase 4: consume the Agent SDK's query() AsyncGenerator<SDKMessage> and
// write the SAME .loki state the embedded bash stream-json parser writes
// (the stream-json parser heredoc in autonomy/run.sh run_autonomous()). This is a faithful TRANSLATION of that Python
// parser, not a new design -- the .loki contract must stay byte-compatible so
// every downstream consumer (dashboard, efficiency writer, event bus, council)
// is unchanged whether the loop ran on the bash `claude` binary or the SDK.
//
// The SDK's typed messages map 1:1 to the stream-json events the Python parser
// consumed:
//   SDKPartialAssistantMessage  (type:'stream_event')  -> live delta text
//   SDKAssistantMessage         (type:'assistant')     -> text + tool_use blocks
//   SDKUserMessage              (type:'user')          -> tool_result blocks
//   SDKResultMessage            (type:'result')        -> cost + exit code
//   (hook events arrive as system messages / are surfaced via the hooks option)
//
// Writes (identical to the Python parser):
//   .loki/state/agents.json                    orchestrator + subagent tracking
//   .loki/events.jsonl                         claude_hook_<name> records
//   .loki/metrics/result-cost-<iter>.json      authoritative per-iter cost
//
// PURE + testable: the consumer takes an async-iterable of SDKMessage-shaped
// objects, so a unit test feeds a canned array (no API call) and asserts the
// exact files. Nothing here imports the Agent SDK at runtime -- the caller
// (providers.ts) owns query(); this only consumes what it yields.

import { appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { num, routerTelemetryOn } from "../engine10/cost.ts";
import { modelOutcome } from "../util/run_identity.ts";
import { partialUsagePath } from "./budget.ts";
import { recordAdvisorError } from "./router/advisor_probe.ts";
import { lokiDirFor } from "../util/paths.ts";
import { neutralizeEngineMarkers } from "./retry_class.ts";

// A structural subset of the Agent SDK's SDKMessage union -- only the fields the
// parser reads. Kept local (not imported from the SDK) so the parser is pure and
// unit-testable with plain objects, and so a minor SDK type churn cannot break
// the parser's contract with the .loki files.
export interface StreamMsg {
  type: string; // 'stream_event' | 'assistant' | 'user' | 'result' | 'system' | ...
  // assistant / user carry a nested message with content blocks
  message?: {
    content?: Array<Record<string, unknown>>;
    // E-98e: per-message usage, present on real assistant turns. A streamed
    // snapshot can repeat one id with growing usage as it fills in.
    id?: string;
    usage?: Record<string, unknown>;
  };
  // stream_event carries a raw streaming event
  event?: {
    type?: string;
    delta?: { type?: string; text?: string };
  };
  // result fields (SDKResultMessage)
  subtype?: string;
  is_error?: boolean;
  total_cost_usd?: number | null;
  duration_ms?: number;
  num_turns?: number;
  modelUsage?: Record<string, Record<string, unknown>>; // SDKResultMessage.modelUsage: per-model, whole pipeline (usage is the main loop only)
  usage?: Record<string, unknown>;
  session_id?: string;
  result?: string; // SDKResultMessage.result (final assistant text summary)
  // SDKAssistantMessage.error: 'rate_limit' | 'overloaded' | ... (structural
  // rate-limit signal). SDKRateLimitEvent carries rate_limit_info.
  error?: string;
  rate_limit_info?: Record<string, unknown>;
  // hook events arrive as type:'system' subtype:'hook_started'|'hook_response'
  // with a hook_event field (SDKHookStartedMessage / SDKHookResponseMessage).
  // NOT a top-level 'hook_event' message (the bash stream-json parser's probe
  // was for the CLI's older shape; the SDK surfaces hooks this way).
  hook_event?: string;
  // E-59: system/init reports the provider's actual model ({"type":"system","subtype":"init",...,"model":"opus"});
  // a result message may also carry it. Never the caller's "sonnet" guess -- writeResultCost records it verbatim.
  model?: string;
  // Refusal / retry system frames (SDKModelRefusalFallbackMessage, SDKModelRefusalNoFallbackMessage, SDKAPIRetryMessage)
  // and the assistant-frame supersede list (SDKAssistantMessage.supersedes).
  uuid?: string;
  supersedes?: string[];
  api_refusal_category?: string | null;
  original_model?: string;
  fallback_model?: string;
  scope?: string;
  retracted_message_uuids?: string[];
  attempt?: number;
  max_retries?: number;
  retry_delay_ms?: number;
  error_status?: number | null;
  tools?: unknown; // system/init: the tool names the session was given (mcp__server__tool for MCP tools)
}

export interface ParserContext {
  cwd: string; // repo root under which .loki lives
  iteration: string; // LOKI_ITERATION stamp for the result-cost file
  hookEventsEnabled: boolean; // LOKI_HOOK_EVENTS != "off"
  requestedModel?: string; // the model the runner resolved for this call (P12-23); absent = no requested/downgrade fields
  // Live-output sink. The caller tees the same text to the terminal +
  // iterationOutputPath + captured log (mirroring the bash `tee`). Default: stdout.
  write?: (s: string) => void;
  /** Called once, at the first frame carrying a session id, so a SIGKILL before stream end still leaves a resumable id (FC-IMPLEMENT-RESUME-STARTS-OVER). */
  onSessionId?: (id: string) => void;
}

interface AgentInfo {
  agent_id: string;
  tool_id: string;
  agent_type: string;
  model: string;
  current_task: string;
  status: string;
  spawned_at: string;
  tasks_completed: string[];
  tool_count?: number;
  completed_at?: string;
}

const ORCHESTRATOR_ID = "orchestrator-main";
// The API reports no per-tool token cost, so tool-definition cost is an estimate (labelled as one everywhere it appears).
const MCP_TOOL_DEF_TOKENS_EST = 150;
const MCP_TOOL_TOKEN_WARN_DEFAULT = 10000;

// nowIso: the parser stamps timestamps like the Python parser
// (datetime.now(timezone.utc).isoformat() with a trailing Z). Injectable for
// deterministic tests.
function nowIso(clock?: () => string): string {
  // Node's toISOString() already yields e.g. 2026-07-13T12:34:56.789Z (UTC, Z
  // suffix) -- the same shape the Python parser produces via isoformat()+"Z".
  return clock ? clock() : new Date().toISOString();
}

/**
 * Consume a stream of SDK messages, writing the same .loki state the bash
 * Python parser writes. Returns the process-equivalent exit code (0 success,
 * 1 on a result error) so the caller can populate ProviderResult.exitCode.
 *
 * `clock` is injectable so unit tests get deterministic timestamps.
 */
export interface StreamResult {
  exitCode: number;
  sessionId?: string;
  totalCostUsd?: number | null;
  // The load-bearing capture: concatenated final assistant text + result.result
  // + any rate-limit error string. The provider writes this to
  // capturedOutputPath so the existing completion-promise / rate-limit /
  // council text scanners fire exactly as on the bash route.
  capturedText: string;
  // Structural rate-limit signal (assistant error 'rate_limit'/'overloaded' or
  // an SDKRateLimitEvent). resetSeconds is the wait if the SDK reported one.
  rateLimit?: { resetSeconds?: number };
  // True iff a terminal `result` message arrived. When false, the loop ended
  // without a result (aborted/crashed) and the caller must treat it as failure.
  sawResult: boolean;
  // True iff the stream ended abnormally (source threw mid-iteration, or no terminal result arrived). The
  // result is then partial: whatever was consumed is kept, exitCode stays 1.
  truncated: boolean;
  // True iff the stream carried a model_refusal_fallback or model_refusal_no_fallback frame. A refused turn is
  // not a crash and not a REJECT: council and reviewer consumers read this as INCONCLUSIVE.
  refused: boolean;
  // True iff a model_refusal_no_fallback frame arrived: nothing replaced the refused turn, so its session must
  // not be resumed (the refusal sits in that session's history).
  refusedNoFallback: boolean;
  // True iff the terminal result frame carried subtype error_max_turns: the session hit its turn cap.
  maxTurns: boolean;
}

export async function consumeSdkStream(
  messages: AsyncIterable<StreamMsg> | Iterable<StreamMsg>,
  ctx: ParserContext,
  clock?: () => string,
): Promise<StreamResult> {
  const write = ctx.write ?? ((s: string) => process.stdout.write(s));
  const lokiRoot = join(ctx.cwd, ".loki");
  const agentsFile = join(lokiRoot, "state", "agents.json");
  // The run ledger honors LOKI_DIR so the writer and the kpis reader (util/paths lokiDir) share one dir.
  const eventsJsonl = join(lokiDirFor(ctx.cwd), "events.jsonl");

  const agents = loadAgents(agentsFile);
  // Always show the main orchestrator (Python init_orchestrator).
  agents[ORCHESTRATOR_ID] = agents[ORCHESTRATOR_ID] ?? {
    agent_id: ORCHESTRATOR_ID,
    tool_id: ORCHESTRATOR_ID,
    agent_type: "orchestrator",
    model: process.env["LOKI_CURRENT_MODEL"] ?? "sonnet",
    current_task: "Initializing...",
    status: "active",
    spawned_at: nowIso(clock),
    tasks_completed: [],
    tool_count: 0,
  };
  saveAgents(agentsFile, agents);

  let streamedText = false; // partial-message deltas already printed this message
  let exitCode = 1; // fail-closed: no result message -> failure (aborted/crashed)
  let sessionId: string | undefined;
  let seenSessionId: string | undefined;
  let sessionModel: string | undefined; // E-59: from system/init, overridden by a result message's own model if present
  let totalCostUsd: number | null | undefined;
  let captured = ""; // load-bearing capture (final assistant text + result.result)
  // Blocks are newline-separated so a line-anchored marker never swallows the next block's prose.
  // Assistant text is remembered per frame uuid so a refusal-fallback retraction can evict exactly that text.
  const textByUuid = new Map<string, string[]>();
  const capture = (raw: string, uuid?: string) => {
    const t = neutralizeEngineMarkers(raw); // FC-AGENT-TEXT-FORGES-ENGINE-MARKER: agent text never writes an engine marker
    captured += (captured && !captured.endsWith("\n") ? "\n" : "") + t;
    if (uuid) textByUuid.set(uuid, [...(textByUuid.get(uuid) ?? []), t]);
  };
  const evict = (uuids: string[] | undefined) => {
    for (const u of uuids ?? []) {
      for (const t of textByUuid.get(u) ?? []) {
        const i = captured.lastIndexOf(t);
        if (i >= 0) captured = captured.slice(0, i) + captured.slice(i + t.length);
      }
      textByUuid.delete(u);
    }
  };
  let refused = false;
  let refusedNoFallback = false;
  let rateLimit: { resetSeconds?: number } | undefined;
  let sawResult = false;
  let maxTurns = false;
  // E-98e: per-message usage, keyed by message.id so a repeated streamed
  // snapshot of the same message is a max, not a double-count. Written to
  // partialUsagePath after every assistant message, so a session killed
  // before `result` (no finally runs: src/cli.ts's SIGTERM handler exits
  // immediately) still leaves its last successful write on disk.
  const usageById = new Map<string, Record<string, number>>();
  let anonUsageId = 0;
  // S41-04: the first assistant message's own input+cache_read+cache_creation
  // sum (the "first-turn prefix" -- everything the SDK sent before any tool
  // output came back). firstTurnId pins WHICH message counts: growing
  // snapshots of that same id keep updating the sum (a streamed usage
  // snapshot grows as it fills in, same as usageById above); a later message
  // with a different id is a later turn and is never folded in.
  let firstTurnId: string | undefined;
  let firstTurnPromptTokens: number | undefined;
  // R1-08: per-request size and advisor telemetry. Keyed by message.id like usageById (a growing
  // snapshot is a max, not a second request). Advisor sub-inferences arrive as usage.iterations
  // entries of type 'advisor_message' (BetaAdvisorMessageIterationUsage, @anthropic-ai/sdk).
  const reqById = new Map<string, RequestUsage>();
  const advisorById = new Map<string, AdvisorUsage>();
  const advisorFaults = new Set<string>(); // #269: one key per distinct advisor error or truncation, so a growing snapshot counts once

  // S1-W2-26: tool-use and skill-navigation telemetry, merged into the result-cost record. A turn is one assistant message id (the SDK may stream its blocks as several messages).
  const toolsByTurn = new Map<string, Set<string>>();
  const skillReads: string[] = [];
  let toolResults = 0, toolErrors = 0, mcpToolCount: number | undefined, anonTurn = 0, mcpToolWarned = false;
  const toolTelemetry = (): Record<string, unknown> => {
    const perTurn = [...toolsByTurn.values()].map((t) => t.size);
    return {
      ...(perTurn.length ? { tools_per_turn: Math.max(...perTurn), tool_turns: perTurn.length, tool_calls: perTurn.reduce((a, b) => a + b, 0) } : {}),
      ...(toolResults ? { tool_results: toolResults, tool_errors: toolErrors, tool_error_rate: toolErrors / toolResults } : {}),
      ...(mcpToolCount !== undefined ? { mcp_tool_count: mcpToolCount, mcp_tool_def_tokens_estimated: mcpToolCount * MCP_TOOL_DEF_TOKENS_EST } : {}),
      ...(skillReads.length ? { skill_module_read: skillReads } : {}),
    };
  };

  const guard = { truncated: false };
  for await (const data of asAsync(messages, guard)) {
    const msgType = data.type ?? "";
    if (typeof data.session_id === "string" && data.session_id) { if (!seenSessionId) { try { ctx.onSessionId?.(data.session_id); } catch { /* best-effort */ } } seenSessionId = data.session_id; } // a truncated turn has no result frame but its session is still resumable

    // --- stream_event: live incremental delta text (--include-partial-messages)
    if (msgType === "stream_event") {
      const ev = data.event ?? {};
      if (ev.type === "message_start") {
        streamedText = false;
      } else if (ev.type === "content_block_delta") {
        const delta = ev.delta ?? {};
        if (delta.type === "text_delta" && delta.text) {
          write(delta.text);
          streamedText = true;
        }
      }
      continue;
    }

    // --- assistant: rate-limit error, text blocks + tool_use blocks
    if (msgType === "assistant") {
      // SDKAssistantMessage.error can be 'rate_limit' | 'overloaded' | ...
      evict(data.supersedes); // refusal-fallback: this frame replaces earlier ones
      const err = data.error;
      if (err === "rate_limit" || err === "overloaded") {
        rateLimit = rateLimit ?? {};
        captured += `\n[${err}]\n`; // so the file-based rate-limit scanner fires
      }
      if (err === "authentication_failed") { // FC-AUTH-CAUSE-ONLY-IN-IMPL-LOG: the structural frame, never prose; retry_class SDK_ERR classifies this exact wording
        const said = neutralizeEngineMarkers((data.message?.content ?? []).map((c) => (c["type"] === "text" ? String(c["text"] ?? "") : "")).join(" ")).replace(/\s+/g, " ").trim().slice(0, 200);
        captured += `\n[sdk-loop error: Failed to authenticate (authentication_failed)${said ? `: ${said}` : ""}]\n`;
      }
      const u = data.message?.usage;
      if (u) {
        const id = data.message?.id ?? `#${anonUsageId++}`;
        const prev = usageById.get(id) ?? {};
        usageById.set(id, {
          input_tokens: Math.max(prev["input_tokens"] ?? 0, num(u["input_tokens"])),
          output_tokens: Math.max(prev["output_tokens"] ?? 0, num(u["output_tokens"])),
          cache_read_input_tokens: Math.max(prev["cache_read_input_tokens"] ?? 0, num(u["cache_read_input_tokens"])),
          cache_creation_input_tokens: Math.max(prev["cache_creation_input_tokens"] ?? 0, num(u["cache_creation_input_tokens"])),
        });
        recordRouterUsage(reqById, advisorById, id, u);
        recordAdvisorFaults(advisorFaults, id, data.message?.content, u, process.env["LOKI_DIR"] ?? lokiRoot);
        writePartialUsage(lokiRoot, ctx.iteration, usageById, data.model ?? sessionModel ?? null);

        if (firstTurnId === undefined) firstTurnId = id;
        if (id === firstTurnId) {
          const merged = usageById.get(id)!;
          firstTurnPromptTokens =
            merged["input_tokens"]! + merged["cache_read_input_tokens"]! + merged["cache_creation_input_tokens"]!;
        }
      }
      const content = data.message?.content ?? [];
      const turnId = data.message?.id ?? `#t${anonTurn++}`;
      for (const item of content) {
        const itype = item["type"] as string | undefined;
        if (itype === "text") {
          const text = (item["text"] as string) ?? "";
          // Capture EVERY final text block (independent of the live-print dedup):
          // the streamedText guard only prevents double-PRINTING, not capture.
          if (text) capture(text, data.uuid);
          if (text && !streamedText) write(text);
        } else if (itype === "tool_use") {
          const tool = (item["name"] as string) ?? "unknown";
          const toolId = (item["id"] as string) ?? "";
          const input = (item["input"] as Record<string, unknown>) ?? {};
          const turnTools = toolsByTurn.get(turnId) ?? new Set<string>();
          turnTools.add(toolId || `anon${turnTools.size}`); toolsByTurn.set(turnId, turnTools);
          const readPath = tool === "Read" ? input["file_path"] : undefined;
          const mod = typeof readPath === "string" ? /(?:^|\/)((?:skills|references)\/[^/]+\.md)$/.exec(readPath)?.[1] : undefined;
          if (mod && !skillReads.includes(mod)) skillReads.push(mod);
          bumpOrchestratorTool(agents, tool, toolDesc(tool, input));

          if (tool === "Task") {
            const toolIdShort = toolId.slice(0, 8);
            agents[toolId] = {
              agent_id: `agent-${toolIdShort}`,
              tool_id: toolId,
              agent_type: (input["subagent_type"] as string) ?? "general-purpose",
              model: (input["model"] as string) ?? "sonnet",
              current_task: (input["description"] as string) ?? "",
              status: "active",
              spawned_at: nowIso(clock),
              tasks_completed: [],
            };
            saveAgents(agentsFile, agents);
          } else if (tool === "TodoWrite") {
            // Mirror the Python TodoWrite enrichment -> .loki/queue/in-progress.json
            const todos = (input["todos"] as Array<Record<string, unknown>>) ?? [];
            const inProgress = todos.filter((t) => t["status"] === "in_progress");
            const enriched = inProgress.map((t, i) => {
              const content = (t["content"] as string) ?? "";
              const activeForm = (t["activeForm"] as string) || content;
              return {
                id: `todo-${i}`,
                type: "todo",
                title: content,
                description:
                  "Internal task tracked by the agent TodoWrite tool. " +
                  "This is LLM scratch, not a PRD-derived work item, so " +
                  "it has no acceptance criteria or user story. " +
                  `Active form: ${activeForm}`,
                source: "claude_code_todowrite",
                priority: "medium",
                payload: { action: content, activeForm },
              };
            });
            saveInProgress(join(lokiRoot, "queue", "in-progress.json"), enriched);
          }
        }
      }
      // saveAgents once per assistant message (orchestrator tool_count updates)
      saveAgents(agentsFile, agents);
      continue;
    }

    // --- user: tool_result blocks -> mark spawned agents complete
    if (msgType === "user") {
      const content = data.message?.content ?? [];
      for (const item of content) {
        if (item["type"] === "tool_result") {
          toolResults++; if (item["is_error"] === true) toolErrors++;
          const toolId = (item["tool_use_id"] as string) ?? "";
          const a = agents[toolId];
          if (a) {
            a.status = "completed";
            a.completed_at = nowIso(clock);
            saveAgents(agentsFile, agents);
          }
        }
      }
      continue;
    }

    // --- hook events (SDK: type:'system', subtypes hook_started/hook_progress/
    // hook_response, each carrying hook_event; gated by includeHookEvents:true on
    // the query() call) -> .loki/events.jsonl as claude_hook_<name>. Key off the
    // TERMINAL frame (hook_response) so one lifecycle -> exactly one record;
    // started/progress would triple-count. ponytail: keying on hook_response is
    // the dedup; if a hook is cancelled and emits no response, that lifecycle is
    // (correctly) not recorded as a completed hook event.
    if (msgType === "system" && data.subtype === "hook_response" && data.hook_event) {
      appendHookEvent(eventsJsonl, data.hook_event, data, ctx.hookEventsEnabled, clock);
      continue;
    }

    // --- system/init: the provider's own model report (E-59), captured for writeResultCost below.
    if (msgType === "system" && data.subtype === "init" && typeof data.model === "string" && data.model) {
      sessionModel = data.model;
      if (Array.isArray(data.tools)) {
        mcpToolCount = data.tools.filter((t) => typeof t === "string" && t.startsWith("mcp__")).length;
        const est = mcpToolCount * MCP_TOOL_DEF_TOKENS_EST, limit = Number(process.env["LOKI_MCP_TOOL_TOKEN_WARN"] ?? MCP_TOOL_TOKEN_WARN_DEFAULT);
        if (!mcpToolWarned && Number.isFinite(limit) && est > limit) { mcpToolWarned = true; write(`[loki] warning: ${mcpToolCount} MCP tools attached, MCP tool definitions cost ~${est} tokens (estimated at ${MCP_TOOL_DEF_TOKENS_EST} per tool, not measured) on every request; detach unused MCP servers or raise LOKI_MCP_TOOL_TOKEN_WARN (currently ${limit}).\n`); }
      }
      continue;
    }

    // --- refusal and retry frames -> one run-ledger event each (always written; not gated by hookEventsEnabled).
    if (msgType === "system" && (data.subtype === "model_refusal_fallback" || data.subtype === "model_refusal_no_fallback")) {
      refused = true;
      const noFallback = data.subtype === "model_refusal_no_fallback";
      if (noFallback) refusedNoFallback = true;
      else evict(data.retracted_message_uuids);
      appendRunEvent(eventsJsonl, noFallback ? "model_refusal_no_fallback" : "model_refusal_fallback", {
        category: data.api_refusal_category ?? null,
        from_model: data.original_model ?? null,
        ...(noFallback ? {} : { to_model: data.fallback_model ?? null, scope: data.scope ?? "session" }),
        session_id: data.session_id ?? null,
      }, clock);
      continue;
    }
    if (msgType === "system" && data.subtype === "api_retry") {
      appendRunEvent(eventsJsonl, "api_retry", {
        attempt: data.attempt ?? null,
        max_retries: data.max_retries ?? null,
        retry_delay_ms: data.retry_delay_ms ?? null,
        error_status: data.error_status ?? null,
        error: data.error ?? null,
        session_id: data.session_id ?? null,
      }, clock);
      continue;
    }

    // --- rate_limit event (SDKRateLimitEvent). The SDK emits one on EVERY call
    // as a status heartbeat with rate_limit_info.status === "allowed" -- that is
    // NOT a rate limit and must be IGNORED (verified live: status:"allowed",
    // resetsAt = the window reset epoch, not a wait). Only signal when the status
    // is actually limiting (anything other than "allowed", e.g. rejected/queued).
    if (msgType === "rate_limit" || msgType === "rate_limit_event" || data.rate_limit_info) {
      const info = data.rate_limit_info;
      const status = info?.["status"];
      // "allowed" is the every-call heartbeat; "allowed_warning" means still
      // allowed but approaching the window limit (a warning, NOT a limit yet).
      // Both are non-limiting -> ignore. Only a genuinely limiting status
      // (rejected/queued/etc.) signals a rate limit + a wait (council polish).
      if (status === undefined || status === "allowed" || status === "allowed_warning") {
        continue; // still allowed -> not a rate limit
      }
      let resetSeconds: number | undefined;
      const resetsAt = info?.["resetsAt"] ?? info?.["retryAfter"];
      if (typeof resetsAt === "number") {
        // retryAfter is seconds-from-now; resetsAt is a future epoch (seconds).
        // Convert an epoch to a wait; treat a small value as already seconds.
        if (resetsAt > 1_000_000) {
          const nowS = clock ? 0 : Math.floor(Date.now() / 1000);
          resetSeconds = nowS > 0 ? Math.max(0, resetsAt - nowS) : undefined;
        } else {
          resetSeconds = resetsAt;
        }
      }
      rateLimit = { resetSeconds };
      captured += "\n[rate_limit]\n";
      continue;
    }

    // --- result: mark all agents complete, write cost, set exit code
    if (msgType === "result") {
      sawResult = true;
      if (data.result) capture(data.result);
      const completedAt = nowIso(clock);
      for (const id of Object.keys(agents)) {
        if (agents[id]!.status === "active") {
          agents[id]!.status = "completed";
          agents[id]!.completed_at = completedAt;
          agents[id]!.current_task = "Session complete";
        }
      }
      const orch = agents[ORCHESTRATOR_ID];
      if (orch) orch.tasks_completed.push(`${orch.tool_count ?? 0} tools used`);
      saveAgents(agentsFile, agents);

      // authoritative per-iteration cost (best-effort; never throws to the loop)
      totalCostUsd = data.total_cost_usd ?? null;
      sessionId = data.session_id;
      if (advisorById.size === 0) recordRouterUsage(new Map(), advisorById, "#result", data.usage ?? {}); // advisor seen only on the result
      writeResultCost(lokiRoot, ctx.iteration, data, data.model ?? sessionModel, firstTurnPromptTokens, { ...routerTelemetry(reqById, advisorById, advisorFaults), ...toolTelemetry() }, ctx.requestedModel);

      maxTurns = data.subtype === "error_max_turns";
      exitCode = data.is_error || maxTurns ? 1 : 0;
      // do not break: a well-formed stream ends after result, but keep draining.
    }
  }

  return { exitCode, sessionId: sessionId ?? seenSessionId, totalCostUsd, capturedText: captured, rateLimit, sawResult, truncated: guard.truncated || !sawResult, refused, refusedNoFallback, maxTurns };
}

// --- helpers (translations of the Python functions) -----------------------

// Degrades a broken source: a throw mid-iteration ends the stream and flags it
// truncated (never propagates); non-object entries are skipped.
async function* asAsync(src: AsyncIterable<StreamMsg> | Iterable<StreamMsg>, guard: { truncated: boolean }): AsyncIterable<StreamMsg> {
  try {
    if ((src as AsyncIterable<StreamMsg>)[Symbol.asyncIterator]) {
      for await (const m of src as AsyncIterable<StreamMsg>) if (m && typeof m === "object") yield m;
    } else {
      for (const m of src as Iterable<StreamMsg>) if (m && typeof m === "object") yield m;
    }
  } catch {
    guard.truncated = true;
  }
}

function loadAgents(agentsFile: string): Record<string, AgentInfo> {
  try {
    if (existsSync(agentsFile)) {
      const arr = JSON.parse(readFileSync(agentsFile, "utf8")) as AgentInfo[];
      const out: Record<string, AgentInfo> = {};
      for (const a of arr) {
        if (a && typeof a === "object") out[a.tool_id ?? a.agent_id] = a;
      }
      return out;
    }
  } catch {
    // ignore -- start fresh, exactly like the Python load_agents except-pass
  }
  return {};
}

function saveAgents(agentsFile: string, agents: Record<string, AgentInfo>): void {
  try {
    mkdirSync(dirname(agentsFile), { recursive: true });
    // Python writes a LIST with indent=2. Match that shape/order-of-insertion.
    writeFileSync(agentsFile, `${JSON.stringify(Object.values(agents), null, 2)}`);
  } catch {
    // best-effort: a state-write failure must never break the loop
  }
}

function saveInProgress(inProgressFile: string, tasks: unknown[]): void {
  try {
    mkdirSync(dirname(inProgressFile), { recursive: true });
    writeFileSync(inProgressFile, `${JSON.stringify(tasks, null, 2)}`);
  } catch {
    // best-effort, mirrors the Python save_in_progress except-pass
  }
}

function bumpOrchestratorTool(
  agents: Record<string, AgentInfo>,
  tool: string,
  desc: string,
): void {
  const o = agents[ORCHESTRATOR_ID];
  if (!o) return;
  o.tool_count = (o.tool_count ?? 0) + 1;
  o.current_task = desc ? `${tool}: ${desc.slice(0, 80)}` : `Using ${tool}...`;
}

// toolDesc: mirror the Python per-tool description extraction exactly.
function toolDesc(tool: string, input: Record<string, unknown>): string {
  const s = (k: string): string => (input[k] as string) ?? "";
  switch (tool) {
    case "Read":
    case "Edit":
    case "Write":
      return s("file_path");
    case "Bash":
      return s("description") || s("command").slice(0, 60);
    case "Grep":
      return `pattern: ${s("pattern")}`;
    case "Glob":
      return s("pattern");
    default:
      return "";
  }
}

// Run-ledger event on the same .loki/events.jsonl stream the hook events use. Best-effort.
function appendRunEvent(eventsJsonl: string, type: string, payload: unknown, clock?: () => string): void {
  try {
    mkdirSync(dirname(eventsJsonl), { recursive: true });
    appendFileSync(eventsJsonl, `${JSON.stringify({ type, source: "claude_cli", timestamp: nowIso(clock), payload })}\n`);
  } catch {
    // best-effort
  }
}

function appendHookEvent(
  eventsJsonl: string,
  eventName: string,
  payload: unknown,
  enabled: boolean,
  clock?: () => string,
): void {
  if (!enabled) return;
  try {
    mkdirSync(dirname(eventsJsonl), { recursive: true });
    const record = {
      type: `claude_hook_${String(eventName).toLowerCase()}`,
      source: "claude_cli",
      timestamp: nowIso(clock),
      payload,
    };
    // Single-process SDK loop: an appendFileSync is atomic enough (the bash
    // route needs flock only because multiple processes tee the same file).
    appendFileSync(eventsJsonl, `${JSON.stringify(record)}\n`);
  } catch {
    // best-effort, like the Python append_hook_event except clause
  }
}

// R1-08. A request is one assistant message; its size is input + cache_read + cache_creation (the
// prompt the model saw). OVER_100K_TOKENS is the Haiku 5.5 long-prompt boundary (strictly above).
const OVER_100K_TOKENS = 100_000;
interface RequestUsage { size: number; output: number }
interface AdvisorUsage { calls: number; input: number; output: number }

function recordRouterUsage(
  reqs: Map<string, RequestUsage>,
  advisors: Map<string, AdvisorUsage>,
  id: string,
  u: Record<string, unknown>,
): void {
  const size = num(u["input_tokens"]) + num(u["cache_read_input_tokens"]) + num(u["cache_creation_input_tokens"]);
  const prev = reqs.get(id);
  reqs.set(id, { size: Math.max(prev?.size ?? 0, size), output: Math.max(prev?.output ?? 0, num(u["output_tokens"])) });
  const its = u["iterations"];
  if (!Array.isArray(its)) return;
  let calls = 0, input = 0, output = 0;
  for (const it of its as Array<Record<string, unknown>>) {
    if (!it || it["type"] !== "advisor_message") continue;
    calls++;
    input += num(it["input_tokens"]) + num(it["cache_read_input_tokens"]) + num(it["cache_creation_input_tokens"]);
    output += num(it["output_tokens"]);
  }
  if (calls === 0) return;
  const old = advisors.get(id);
  if (!old || calls >= old.calls) advisors.set(id, { calls, input, output });
}

// #269: advisor error results (an advisor_tool_result block whose content is advisor_tool_result_error) and advisor sub-calls cut off
// at max_tokens. Each distinct fault is keyed once and handed to the existing recordAdvisorError (sticky marker, first message wins).
function recordAdvisorFaults(faults: Set<string>, id: string, content: unknown, u: Record<string, unknown>, runDir: string): void {
  if (!routerTelemetryOn()) return;
  const note = (key: string, message: string): void => {
    if (faults.has(key)) return;
    faults.add(key);
    recordAdvisorError(runDir, message);
  };
  if (Array.isArray(content)) {
    for (const [i, item] of (content as Array<Record<string, unknown>>).entries()) {
      const res = item?.["type"] === "advisor_tool_result" ? (item["content"] as Record<string, unknown> | undefined) : undefined;
      if (res?.["type"] === "advisor_tool_result_error") note(`err:${id}:${String(item["tool_use_id"] ?? i)}`, `advisor tool error: ${String(res["error_code"] ?? "unknown")}`);
    }
  }
  const its = u["iterations"];
  if (Array.isArray(its)) {
    let n = 0;
    for (const it of its as Array<Record<string, unknown>>) {
      if (it?.["type"] !== "advisor_message") continue;
      if (it["stop_reason"] === "max_tokens") note(`trunc:${id}:${n}`, "advisor sub-call truncated (stop_reason max_tokens)");
      n++;
    }
  }
}

function routerTelemetry(reqs: Map<string, RequestUsage>, advisors: Map<string, AdvisorUsage>, faults: Set<string>): Record<string, number> | undefined {
  if (!routerTelemetryOn()) return undefined; // flag off: result-cost file stays byte-identical to pre-router
  if (reqs.size === 0 && advisors.size === 0 && faults.size === 0) return undefined; // nothing streamed: keep the file shape unchanged
  let over = 0, maxSize = 0, overIn = 0, overOut = 0;
  for (const r of reqs.values()) {
    maxSize = Math.max(maxSize, r.size);
    if (r.size > OVER_100K_TOKENS) { over++; overIn += r.size; overOut += r.output; }
  }
  let truncated = 0;
  for (const k of faults) if (k.startsWith("trunc:")) truncated++;
  let calls = 0, aIn = 0, aOut = 0;
  for (const a of advisors.values()) { calls += a.calls; aIn += a.input; aOut += a.output; }
  return {
    requests_total: reqs.size,
    requests_over_100k: over,
    max_request_tokens: maxSize,
    over_100k_input_tokens: overIn,
    over_100k_output_tokens: overOut,
    advisor_calls: calls,
    advisor_input_tokens: aIn,
    advisor_output_tokens: aOut,
    ...(faults.size > 0 ? { advisor_errors: faults.size } : {}),
    ...(truncated > 0 ? { advisor_truncated: truncated } : {}),
  };
}

// model is the provider-reported model (E-59: from system/init or the result message itself, never
// the caller's guess); shared with the legacy SDK loop, so this only ADDS the key, never touches an
// existing one, and omits it entirely (rather than writing null) when no session reported one.
function modelUsageFields(data: StreamMsg): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  const mu = data.modelUsage;
  if (mu && typeof mu === "object") {
    const n = (v: unknown): number => (typeof v === "number" && Number.isFinite(v) ? v : 0);
    out["model_usage"] = Object.fromEntries(Object.entries(mu).map(([k, v]) => [k, { input_tokens: n(v["inputTokens"]), output_tokens: n(v["outputTokens"]), cache_read_tokens: n(v["cacheReadInputTokens"]), cache_creation_tokens: n(v["cacheCreationInputTokens"]), cost_usd: n(v["costUSD"]) }]));
  }
  const cc = (data.usage as Record<string, unknown> | undefined)?.["cache_creation"] as Record<string, unknown> | undefined;
  if (cc && typeof cc["ephemeral_5m_input_tokens"] === "number" && typeof cc["ephemeral_1h_input_tokens"] === "number") { out["cache_creation_5m_tokens"] = cc["ephemeral_5m_input_tokens"]; out["cache_creation_1h_tokens"] = cc["ephemeral_1h_input_tokens"]; }
  return out;
}

function writeResultCost(
  lokiRoot: string,
  iteration: string,
  data: StreamMsg,
  model?: string,
  firstTurnPromptTokens?: number,
  router?: Record<string, unknown>,
  requested?: string,
): void {
  try {
    const cost = data.total_cost_usd;
    if (cost === undefined || cost === null) return; // Python skips when None
    const u = (data.usage ?? {}) as Record<string, number>;
    const rec = {
      total_cost_usd: cost,
      input_tokens: u["input_tokens"] ?? 0,
      output_tokens: u["output_tokens"] ?? 0,
      // RECEIPT-TRUTH: a usage block without the cache keys leaves them out of the file (NOT RECORDED), not a measured 0
      ...(typeof u["cache_read_input_tokens"] === "number" ? { cache_read_tokens: u["cache_read_input_tokens"] } : {}),
      ...(typeof u["cache_creation_input_tokens"] === "number" ? { cache_creation_tokens: u["cache_creation_input_tokens"] } : {}),
      ...(typeof data.duration_ms === "number" ? { duration_ms: data.duration_ms } : {}),
      ...(typeof data.num_turns === "number" ? { num_turns: data.num_turns } : {}),
      ...(typeof data.session_id === "string" && data.session_id ? { session_id: data.session_id } : {}),
      ...(process.env["LOKI_E10_RESUME_SESSION"] ? { resumed_from: process.env["LOKI_E10_RESUME_SESSION"] } : {}),
      // P12-21: the caller's stage and attempt (env, like the resume id), so cost_breakdown can attribute per stage and retry
      ...(process.env["LOKI_E10_STAGE"] ? { stage: process.env["LOKI_E10_STAGE"] } : {}),
      ...(Number(process.env["LOKI_E10_ATTEMPT"]) >= 1 ? { attempt: Math.floor(Number(process.env["LOKI_E10_ATTEMPT"])) } : {}),
      ...modelUsageFields(data),
      ...(model ? { model } : {}),
      ...(model && requested ? { requested_model: requested, model_downgraded: modelOutcome(requested, model).downgraded } : {}), // P12-23 Q3: requested vs actual
      ...(firstTurnPromptTokens !== undefined ? { first_turn_prompt_tokens: firstTurnPromptTokens } : {}),
      ...(router ?? {}),
    };
    const dir = join(lokiRoot, "metrics");
    mkdirSync(dir, { recursive: true });
    const target = join(dir, `result-cost-${iteration}.json`);
    const tmp = `${target}.tmp`;
    writeFileSync(tmp, JSON.stringify(rec));
    renameSync(tmp, target); // os.replace equivalent (atomic)
  } catch {
    // best-effort, mirrors the Python try/except pass
  }
}

// E-98e: the running SUM across all message ids seen so far, written after
// every assistant message. Best-effort and atomic, same as writeResultCost;
// left on disk after a normal completion too (nothing globs the
// `partial-usage-` prefix, so a stale file is inert, same as an old
// result-cost file already left behind today).
function writePartialUsage(lokiRoot: string, iteration: string, usageById: Map<string, Record<string, number>>, model: string | null): void {
  try {
    const sum = { input_tokens: 0, output_tokens: 0, cache_read_tokens: 0, cache_creation_tokens: 0, model };
    for (const v of usageById.values()) {
      sum.input_tokens += v["input_tokens"] ?? 0;
      sum.output_tokens += v["output_tokens"] ?? 0;
      sum.cache_read_tokens += v["cache_read_input_tokens"] ?? 0;
      sum.cache_creation_tokens += v["cache_creation_input_tokens"] ?? 0;
    }
    const target = partialUsagePath(lokiRoot, iteration);
    mkdirSync(dirname(target), { recursive: true });
    const tmp = `${target}.tmp`;
    writeFileSync(tmp, JSON.stringify(sum));
    renameSync(tmp, target);
  } catch {
    // best-effort, mirrors writeResultCost's try/except pass
  }
}
