// loki-ts/src/commands/trust.ts -- R4 `loki trust` subcommand.
//
// Visible trust trajectory: shows whether the agent is EARNING autonomy on THIS
// repo over time (council pass-rate, gate pass-rate, iterations-to-completion,
// human interventions), each trending up/down/flat. Derived read-only from the
// per-run proof-of-run history under .loki/proofs/. No new instrumentation.
//
// `loki kpis` stays a single-run snapshot; `loki trust` is the across-runs
// trajectory. They are complementary, not duplicates.
//
// Usage:
//   loki trust            -- pretty-print the trajectory
//   loki trust --json     -- machine-readable JSON
//   loki trust --help     -- usage
//
// Exit codes: 0 on success (including insufficient/empty history), 1 only on a
// flag parse error.
import {
  computeTrajectory,
  formatTrajectoryHuman,
  formatTrajectoryJson,
  writeTrajectoryCache,
} from "../metrics/trust.ts";
import type { AutonomyLevel } from "../metrics/trust.ts";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { renderProofBadge } from "./proof.ts";
import { dirname, join } from "node:path";
import { safeGit } from "../util/safe_git.ts";
import { lokiDir as defaultLokiDir } from "../util/paths.ts";

// Read-only: the current autonomy level from .loki/policies.json (JSON only).
// Missing, unparseable or unknown level is null (no level set), never a guess.
function currentAutonomy(lokiDir: string): AutonomyLevel | null {
  const f = join(lokiDir, "policies.json");
  if (!existsSync(f)) return null;
  try {
    const v = (JSON.parse(readFileSync(f, "utf8")) as { autonomy?: unknown }).autonomy;
    return v === "propose" || v === "execute" || v === "operate" ? v : null;
  } catch {
    return null;
  }
}

// README badge for the newest proof whose honesty.headline is recognized (same
// renderer as `loki proof badge`, so green is VERIFIED only). Null when none.
function lastSealedBadge(lokiDir: string): string | null {
  const dir = join(lokiDir, "proofs");
  let ids: string[] = [];
  try {
    ids = readdirSync(dir, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name)
      .sort()
      .reverse();
  } catch {
    return null;
  }
  for (const id of ids) {
    try {
      const d = JSON.parse(readFileSync(join(dir, id, "proof.json"), "utf8")) as {
        honesty?: { headline?: unknown };
      };
      const h = d.honesty?.headline;
      const md = renderProofBadge(typeof h === "string" ? h : null);
      if (md) return md;
    } catch {
      continue;
    }
  }
  return null;
}

export interface PathSeal {
  path: string;
  /** Receipts naming this path whose sealed headline is exactly VERIFIED. */
  verified: number;
  /** Receipts naming this path with any other headline (or none). */
  other: number;
  /** Revert commits in git history that touched this path; null when history is unreadable. */
  reverts: number | null;
}

// Paths touched by revert commits (subject `Revert "..."` or a "This reverts
// commit" body line, which also covers a reverted merge). Null when the
// directory is not a readable, full-history git repo. Argument arrays only, via safeGit.
function revertCounts(repoDir: string): Map<string, number> | null {
  let log: string;
  try {
    // A shallow clone truncates history, so a count would silently undercount; anything but an explicit "false" is unknown.
    if (safeGit(repoDir, ["rev-parse", "--is-shallow-repository"]).trim() !== "false") return null;
    log = safeGit(repoDir, ["log", "--format=%H%x1f%B%x1e"]);
  } catch {
    return null;
  }
  const counts = new Map<string, number>();
  for (const rec of log.split("\x1e")) {
    const [sha, body] = rec.trim().split("\x1f");
    if (!sha || body === undefined) continue;
    if (!/^Revert "/.test(body) && !/^This reverts commit [0-9a-f]{7,40}/m.test(body)) continue;
    let names: string;
    try {
      names = safeGit(repoDir, ["show", "-z", "--name-only", "--no-renames", "--format=", "-m", "--first-parent", sha]);
    } catch {
      return null; // an unreadable revert commit makes every count unknown, never a silent undercount
    }
    // -z: NUL-separated, unquoted paths (a quoted octal-escaped name would never match a receipt path)
    for (const p of new Set(names.split("\0").filter((l) => l.length > 0))) {
      counts.set(p, (counts.get(p) ?? 0) + 1);
    }
  }
  return counts;
}

// Per-path Seal record: each proof.json lists the paths it changed in
// files_changed.files[].path (the list the generator already records); the verdict is honesty.headline (else verdict). Reverts come
// from git history. Read-only; paths no receipt names are not listed.
export function computePathSeals(lokiDir: string, repoDir: string = dirname(lokiDir)): PathSeal[] {
  const byPath = new Map<string, PathSeal>();
  const reverts = revertCounts(repoDir);
  const dir = join(lokiDir, "proofs");
  let ids: string[] = [];
  try {
    ids = readdirSync(dir, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort();
  } catch {
    return [];
  }
  for (const id of ids) {
    let d: { files_changed?: { files?: unknown }; honesty?: { headline?: unknown }; verdict?: unknown };
    try {
      d = JSON.parse(readFileSync(join(dir, id, "proof.json"), "utf8"));
    } catch {
      continue;
    }
    const files = d.files_changed?.files;
    if (!Array.isArray(files)) continue;
    const h = d.honesty?.headline ?? d.verdict;
    const ok = typeof h === "string" && h.trim().toUpperCase() === "VERIFIED";
    for (const f of files) {
      const p = (f as { path?: unknown } | null)?.path;
      if (typeof p !== "string" || p === "") continue;
      const e = byPath.get(p) ?? { path: p, verified: 0, other: 0, reverts: reverts === null ? null : (reverts.get(p) ?? 0) };
      if (ok) e.verified++;
      else e.other++;
      byPath.set(p, e);
    }
  }
  return [...byPath.values()].sort((a, b) => a.path.localeCompare(b.path));
}

// ---- Earned-merge policy: the ONE place the threshold, protected-path and
// revert rules live. The merge gate (autonomy/loki _pr_earned_merge_check) asks
// `loki trust --check` and the per-path display below calls the same function.
export interface EarnedPolicy {
  minVerified: number;
  protectedGlobs: string[];
}

export type EarnedCode = "eligible" | "protected" | "no-record" | "reverts-unknown" | "reverted" | "below-threshold";

export interface EarnedDecision {
  path: string;
  eligible: boolean;
  code: EarnedCode;
  /** The refusal reason (gate wording, starts with the path); null when eligible. */
  reason: string | null;
  /** More VERIFIED receipts needed to reach the minimum (0 when met). */
  needed: number;
}

const BUILTIN_PROTECTED = [".github/*", ".loki/*", ".env", ".env.*", "*/.env", "*/.env.*", ".envrc", "*/.envrc", "codeowners", "docs/codeowners"];

// Default 20, floor 1; a value that is not all digits falls back to the default.
export function earnedPolicyFromEnv(env: Record<string, string | undefined> = process.env): EarnedPolicy {
  const raw = env.LOKI_EARNED_MERGE_MIN_VERIFIED;
  const n = raw !== undefined && /^[0-9]+$/.test(raw) ? Number(raw) : 20;
  const globs = (env.LOKI_EARNED_MERGE_PROTECTED ?? "").toLowerCase().split(/\s+/).filter((g) => g !== "");
  return { minVerified: Math.max(1, n), protectedGlobs: globs };
}

const escRe = (c: string): string => c.replace(/[\\^$.*+?()[\]{}|/-]/g, "\\$&");
const POSIX_CLASS: Record<string, string> = {
  alnum: "a-zA-Z0-9", alpha: "a-zA-Z", digit: "0-9", lower: "a-z", upper: "A-Z", space: " \\t\\n\\r\\f\\v",
  blank: " \\t", punct: "!-\\/:-@\\[-`{-~", xdigit: "0-9a-fA-F", word: "a-zA-Z0-9_", cntrl: "\\x00-\\x1f\\x7f", print: "\\x20-\\x7e", graph: "\\x21-\\x7e",
};

// Bracket expression starting at glob[i] === "[": returns the regex and the
// index of the closing "]", or null when unterminated (then "[" is literal, as in bash).
function bracket(glob: string, i: number): { re: string; end: number } | null {
  let j = i + 1;
  let neg = false;
  if (glob[j] === "!" || glob[j] === "^") {
    neg = true;
    j++;
  }
  let body = "";
  let first = true;
  for (; j < glob.length; j++) {
    const c = glob[j] as string;
    if (c === "]" && !first) return { re: `[${neg ? "^" : ""}${body}]`, end: j };
    first = false;
    if (c === "[" && glob[j + 1] === ":") {
      const close = glob.indexOf(":]", j + 2);
      const cls = close === -1 ? undefined : POSIX_CLASS[glob.slice(j + 2, close)];
      if (cls !== undefined) {
        body += cls;
        j = close + 1;
        continue;
      }
    }
    // Collating symbols [.x.] and equivalence classes [=x=] depend on the locale.
    // Not emulated: the glob is treated as matching every path (fail closed).
    if (c === "[" && (glob[j + 1] === "." || glob[j + 1] === "=")) throw new Error("unsupported bracket element");
    if (c === "\\" && j + 1 < glob.length) {
      body += escRe(glob[++j] as string);
      continue;
    }
    body += c === "-" ? "-" : escRe(c);
  }
  return null;
}

// Shell-style glob, the dialect of a bash `case` pattern: * spans any
// characters including "/", ? is one character, [..] / [!..] / [^..] are
// bracket classes, a backslash makes the next character literal.
function globMatch(glob: string, text: string): boolean {
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i] as string;
    if (c === "*") re += ".*";
    else if (c === "?") re += ".";
    else if (c === "\\" && i + 1 < glob.length) re += escRe(glob[++i] as string);
    else if (c === "[") {
      const b = bracket(glob, i);
      if (b) {
        re += b.re;
        i = b.end;
      } else re += escRe(c);
    } else re += escRe(c);
  }
  return new RegExp(`^${re}$`, "s").test(text);
}

// The refusal reason when a protected glob matches the path, else null. A glob
// that cannot be evaluated (collating symbol, equivalence class, reversed
// range) refuses every path and names the glob, never crashes.
function protectedReason(path: string, policy: EarnedPolicy): string | null {
  const lp = path.toLowerCase();
  for (const g of [...BUILTIN_PROTECTED, ...policy.protectedGlobs]) {
    try {
      if (globMatch(g, lp)) return `${path} is a protected path`;
    } catch {
      return `${path} is refused: the protected glob "${g}" cannot be evaluated, so every path is refused`;
    }
  }
  return null;
}

export function isProtectedPath(path: string, policy: EarnedPolicy): boolean {
  return protectedReason(path, policy) !== null;
}

// Order is the gate's order: protected, no record, reverts, then the floor.
export function earnedMergeDecision(path: string, seal: PathSeal | undefined, policy: EarnedPolicy): EarnedDecision {
  const refuse = (code: EarnedCode, reason: string, needed: number): EarnedDecision => ({ path, eligible: false, code, reason, needed });
  const needed = Math.max(0, policy.minVerified - (seal?.verified ?? 0));
  const prot = protectedReason(path, policy);
  if (prot !== null) return refuse("protected", prot, needed);
  if (!seal) return refuse("no-record", `${path} has no Seal record`, needed);
  if (seal.reverts === null) return refuse("reverts-unknown", `${path} revert status is unknown`, needed);
  if (seal.reverts !== 0) return refuse("reverted", `${path} has ${seal.reverts} recorded revert(s)`, needed);
  if (seal.verified < policy.minVerified) return refuse("below-threshold", `${path} has ${seal.verified} VERIFIED receipts, need ${policy.minVerified}`, needed);
  return { path, eligible: true, code: "eligible", reason: null, needed: 0 };
}

function progressText(d: EarnedDecision): string {
  switch (d.code) {
    case "eligible": return "eligible for earned merge";
    case "below-threshold": return `${d.needed} more needed`;
    case "protected": return "refused: protected path, always PR-only";
    case "reverted": return "refused: reverted in git history";
    case "reverts-unknown": return "refused: reverts unknown (shallow clone or unreadable history)";
    default: return "refused: no Seal record";
  }
}

function formatPathSeals(seals: PathSeal[], policy: EarnedPolicy): string {
  if (seals.length === 0) return "";
  const rows = seals.map((s) => {
    const rv = s.reverts === null ? "reverts unknown" : `${s.reverts} reverts`;
    return `  ${s.path}: ${s.verified} of ${policy.minVerified} VERIFIED, ${s.other} other, ${rv}, ${progressText(earnedMergeDecision(s.path, s, policy))}`;
  });
  const head = `Earned-merge policy: ${policy.minVerified} VERIFIED receipts and 0 reverts per path (display only; auto-merge stays off unless LOKI_EARNED_MERGE=1)`;
  return `\nPer-path Seal record:\n${head}\n${rows.join("\n")}\n`;
}

// `loki trust --check`: the merge gate's own decision, one line per input path:
// "ok<TAB>path" or "refuse<TAB>path<TAB>reason".
function formatChecks(paths: string[], seals: PathSeal[], policy: EarnedPolicy): string {
  const by = new Map(seals.map((s) => [s.path, s]));
  return paths
    .map((p) => {
      const d = earnedMergeDecision(p, by.get(p), policy);
      return d.eligible ? `ok\t${p}\n` : `refuse\t${p}\t${d.reason}\n`;
    })
    .join("");
}

const HELP = `loki trust -- visible trust trajectory (R4)

Usage:
  loki trust             Pretty-print the per-project trust trajectory
  loki trust --json      Emit the trajectory as JSON
  loki trust --check     Read paths (one per line) from stdin and print the
                         earned-merge decision for each (used by the merge gate)
  loki trust --help      Show this help

Shows whether the agent is earning autonomy on THIS repo over time:
  - Council pass rate        (higher is better)
  - Gate pass rate           (higher is better)
  - Iterations to completion (lower is better)
  - Human interventions      (lower is better, when recorded)

It also prints a "Per-path Seal record" (VERIFIED receipts and git reverts
per changed path; proof.json files_changed) with each path's progress toward
the earned-merge policy (LOKI_EARNED_MERGE_MIN_VERIFIED, default 20, and zero
reverts) and why a path is refused (protected, reverted, reverts unknown), and an "Outcome effort" block: accepted outcomes, misleading
completion rate (false VERIFIED over VERIFIED claims), cost per accepted
(n/a when any cost is unmeasured), interventions by type, and minutes per
accepted (waited, upper bound; active minutes are not measured). Definitions:
docs/EVALUATING.md "Outcome analytics".

Derived read-only from proof-of-run history in .loki/proofs/. With fewer
than 2 recorded runs it reports "not enough history yet" rather than a
fabricated trend. Also prints advisory earned-autonomy advice (eligible for the
next level after 10+ runs with recorded verdicts, zero false VERIFIED and no
regressing axis); it never writes the policy file. Complements 'loki kpis' (single-run snapshot). Also prints a copyable README badge
snippet for the last sealed run (or the next step when there is none).
`;

export function runTrust(args: readonly string[], stdin?: string): number {
  let asJson = false;
  let check = false;
  for (const a of args) {
    if (a === "--help" || a === "-h" || a === "help") {
      process.stdout.write(HELP);
      return 0;
    }
    if (a === "--json") {
      asJson = true;
      continue;
    }
    if (a === "--check") {
      check = true;
      continue;
    }
    process.stderr.write(
      `loki trust: unknown arg: ${a}\nRun 'loki trust --help' for usage.\n`,
    );
    return 1;
  }
  const lokiDir = defaultLokiDir();
  const policy = earnedPolicyFromEnv();
  if (check) {
    let input = stdin;
    if (input === undefined) {
      try {
        input = readFileSync(0, "utf8");
      } catch {
        input = "";
      }
    }
    const paths = input.split("\n").filter((l) => l !== "");
    process.stdout.write(formatChecks(paths, computePathSeals(lokiDir), policy));
    return 0;
  }
  const traj = computeTrajectory(lokiDir, currentAutonomy(lokiDir));
  // Best-effort cache so the CLI, dashboard, and bash fallback share one
  // source of truth (parity with the bash route + dashboard endpoint).
  writeTrajectoryCache(lokiDir, traj);
  const seals = computePathSeals(lokiDir);
  if (asJson) {
    const base = JSON.parse(formatTrajectoryJson(traj)) as Record<string, unknown>;
    process.stdout.write(JSON.stringify({ ...base, path_seals: seals }, null, 2) + "\n");
  } else {
    process.stdout.write(formatTrajectoryHuman(traj) + "\n" + formatPathSeals(seals, policy));
  }
  if (!asJson) {
    const badge = lastSealedBadge(lokiDir);
    process.stdout.write(
      badge
        ? `\nREADME badge for the last sealed run (copy-paste markdown):\n${badge}\n`
        : "\nNo README badge yet: no sealed run. Next step: run 'loki start' to completion, then 'loki trust'.\n",
    );
  }
  return 0;
}
